// Lists the custom elements registered by @wokwi/elements and writes
// src/lib/catalog/wokwi-tags.generated.ts, which the catalog validator uses to
// check that a part's `wokwi.tag` really exists.
//
//   npm run gen:wokwi-tags
//
// src/lib/catalog/wokwi-tags.test.ts fails when the generated file is out of date.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const dir = path.join(root, "node_modules/@wokwi/elements/dist/esm");
const out = path.join(root, "src/lib/catalog/wokwi-tags.generated.ts");

const tags = new Set();
for (const file of readdirSync(dir)) {
  if (!file.endsWith(".js") || file.endsWith(".spec.js")) continue;
  const text = readFileSync(path.join(dir, file), "utf8");
  for (const m of text.matchAll(/customElement\(\s*['"](wokwi-[a-z0-9-]+)['"]\s*\)/g)) {
    tags.add(m[1]);
  }
}
const sorted = [...tags].sort();
if (sorted.length === 0) throw new Error("No wokwi elements found in " + dir);

const body = [
  "// GENERATED by scripts/gen-wokwi-tags.mjs from node_modules/@wokwi/elements. Do not edit.",
  "// Run `npm run gen:wokwi-tags` after upgrading @wokwi/elements.",
  "",
  "export const WOKWI_TAGS: ReadonlySet<string> = new Set([",
  ...sorted.map((t) => `  "${t}",`),
  "]);",
  "",
].join("\n");
writeFileSync(out, body);
console.log(`Wrote ${sorted.length} tags to ${path.relative(root, out)}`);
